const lead = $input.item.json;
const normalizarTel = (tel) => {
  if (!tel) return null;
  const digits = tel.toString().replace(/\D/g, '');
  return digits.slice(-8);
};
const normalizarBuyerPhone = (tel) => {
  if (!tel) return null;
  let digits = tel.toString().replace(/\D/g, '');
  if (digits.startsWith('549')) return '+' + digits;
  if (digits.startsWith('54')) return '+549' + digits.slice(2);
  if (digits.startsWith('9') && digits.length >= 10) return '+54' + digits;
  return '+549' + digits;
};
const sufijo1 = normalizarTel(lead.asesor_phone);
const sufijo2 = normalizarTel(lead.asesor_phone2);
return {
  json: {
    ...lead,
    buyer_phone: normalizarBuyerPhone(lead.buyer_phone),
    asesor_sufijo1: sufijo1 || '',
    asesor_sufijo2: sufijo2 || ''
  }
};

const sfResponse = $input.item.json;
const prev = $('PayloadSF').item.json;

const sfLeadId = sfResponse?.LeadId || sfResponse?.id || sfResponse?.leadId || sfResponse?.prospect_id || null;
const success = sfResponse && !sfResponse.error && !sfResponse.message?.toLowerCase().includes('error');

return {
  json: {
    lead_id: prev.lead_id,
    sf_lead_id: sfLeadId,
    new_status: success ? 'sent' : 'error',
    sf_response: JSON.stringify(sfResponse)
  }
};

const asesor = $input.item.json;
const lead = $('⚙️ Normalizar teléfonos').item.json;

const origen = asesor?.origen_sf || lead.origen_sf || 'Mercado Libre Palermo';
const bocaVenta = asesor?.boca_venta || 'CFED';
const asesorEmail = asesor?.email || null;
const asesorNombre = asesor?.nombre || null;

const todayDate = new Date().toISOString().split('T')[0];

const nombreParts = (lead.buyer_nombre || '').trim().split(' ');
const firstName = nombreParts.slice(0, -1).join(' ') || nombreParts[0] || '';
const lastName = nombreParts.slice(-1)[0] || '';
const getModelCode = (titulo) => {
  const modeloLower = (titulo || '').toLowerCase();
  if (modeloLower.includes('hilux')) return '1';
  else if (modeloLower.includes('corolla cross')) return '245';
  else if (modeloLower.includes('corolla') && !modeloLower.includes('cross')) return '2';
  else if (modeloLower.includes('yaris')) return '227';
  else if (modeloLower.includes('etios')) return '225';
  else if (modeloLower.includes('sw4')) return '226';
  else if (modeloLower.includes('hiace')) return '224';
  else if (modeloLower.includes('rav4') || modeloLower.includes('rav 4')) return '3';
  else return '';
};
const getModelName = (titulo) => {
  const modeloLower = (titulo || '').toLowerCase();
  if (modeloLower.includes('hilux')) return 'Hilux';
  else if (modeloLower.includes('corolla cross')) return 'Corolla Cross';
  else if (modeloLower.includes('corolla') && !modeloLower.includes('cross')) return 'Corolla';
  else if (modeloLower.includes('yaris')) return 'Yaris';
  else if (modeloLower.includes('etios')) return 'Etios';
  else if (modeloLower.includes('sw4')) return 'SW4';
  else if (modeloLower.includes('hiace')) return 'Hiace';
  else if (modeloLower.includes('rav4') || modeloLower.includes('rav 4')) return 'RAV4';
  else return titulo || '';
};
const payload = {
  prospect: {
    requestdate: todayDate,
    customer: {
      interest: lead.item_condition === 'used' ? 'USADO' : 'Convencional',
      productInterest: lead.item_titulo || '',
      contacts: [
        {
          names: [
            { part: 'first', value: firstName },
            { part: 'last', value: lastName }
          ],
          phones: [
            { type: 'mobile', field: 'Phone', value: lead.buyer_phone || '' },
            { type: 'mobile', field: 'MobilePhone', value: lead.buyer_phone || '' }
          ],
          ...(lead.buyer_email ? { emails: [{ value: lead.buyer_email }] } : {})
        }
      ],
      comments: `Publicación: ${lead.item_id} | Precio: ${lead.item_precio} | Link: ${lead.item_permalink || ''} | Asesor: ${asesorNombre || ''} | Mail asesor: ${asesorEmail || ''} | Teléfono asesor: ${lead.asesor_phone || ''}`
    },
    vehicles: [
      {
        make: 'Toyota',
        model: getModelName(lead.item_titulo),
        code: getModelCode(lead.item_titulo)
      }
    ],
    provider: {
      name: {
        value: 'Bot-Whatsapp',
        origin: origen
      }
    },
    advisor: asesorEmail ? { email: asesorEmail } : undefined,
    'boca de venta': bocaVenta
  }
};

return {
  json: {
    lead_id: lead.id,
    user_id: lead.user_id,
    destino: lead.destino,
    payload,
    asesor_email: asesorEmail,
    asesor_nombre: asesorNombre
  }
};

const data = $input.item.json;

const sfLeadId = data.sf_lead_id ? `'${data.sf_lead_id}'` : 'NULL';
const sfResponse = (data.sf_response || '').replace(/'/g, "''");

return {
  json: {
    query: `UPDATE meli_leads SET status = '${data.new_status}', sf_lead_id = ${sfLeadId}, sf_response = '${sfResponse}' WHERE id = '${data.lead_id}'`
  }
};

const body = $input.item.json.body;
const { tel_sufijo, updates } = body;

if (!tel_sufijo || !updates || Object.keys(updates).length === 0) {
  throw new Error('Faltan parámetros');
}

const setClauses = Object.entries(updates)
  .map(([key, value]) => {
    if (typeof value === 'number') return `${key} = ${value}`;
    return `${key} = '${String(value).replace(/'/g, "''")}'`;
  })
  .join(', ');

return {
  json: {
    query: `UPDATE meli_leads SET ${setClauses} WHERE RIGHT(REGEXP_REPLACE(buyer_phone, '[^0-9]', ''), 8) = '${tel_sufijo}' AND status IN ('active', 'sent')`
  }
};

